  'A new reminder counts from today and the odometer now.': 'புதிய நினைவூட்டல் இன்றைய தேதி மற்றும் தற்போதைய ஓடோமீட்டரிலிருந்து கணக்கிடப்படும்.',
  'A new state must hold this long before it counts.': 'புதிய நிலை கணக்கில் வர இவ்வளவு நேரம் நீடிக்க வேண்டும்.',
  'A new version is available. Reload the page to continue.': 'புதிய பதிப்பு உள்ளது. தொடர பக்கத்தை மீண்டும் ஏற்றவும்.',
  'A pack writes a ready-made set of alert settings at the {{level}} level. Existing settings for the same alert types are replaced.': 'ஒரு பேக் {{level}} நிலையில் தயாரான எச்சரிக்கை அமைப்புகளை எழுதும். அதே எச்சரிக்கை வகைகளுக்கான தற்போதைய அமைப்புகள் மாற்றப்படும்.',
  'A partner (reseller) buys licences in bulk and allocates them to its customers. Its own company account’s admins manage the partner pool.': 'கூட்டாளர் (மறுவிற்பனையாளர்) உரிமங்களை மொத்தமாக வாங்கி தன் வாடிக்கையாளர்களுக்கு ஒதுக்குவார். அவரது சொந்த நிறுவனக் கணக்கின் நிர்வாகிகள் கூட்டாளர் தொகுப்பை நிர்வகிப்பார்கள்.',
  'A polygon can have at most {{count}} points': 'பலகோணத்தில் அதிகபட்சம் {{count}} புள்ளிகள் இருக்கலாம்',
  'A polygon needs at least 3 points': 'பலகோணத்துக்கு குறைந்தது 3 புள்ளிகள் தேவை',
  'A rectangle needs 4 corners': 'செவ்வகத்துக்கு 4 மூலைகள் தேவை',
  'A stop this long resets driving': 'இவ்வளவு நீண்ட நிறுத்தம் ஓட்டுதலை மீட்டமைக்கும்',
  'A stop within this distance counts as a visit.': 'இந்தத் தூரத்துக்குள் நிற்கும் நிறுத்தம் வருகையாகக் கணக்கிடப்படும்.',
  'A test notification is on its way to this phone.': 'இந்த போனுக்கு ஒரு சோதனை அறிவிப்பு அனுப்பப்படுகிறது.',
  'A trip ended (sent within about a minute).': 'ஒரு பயணம் முடிந்தது (சுமார் ஒரு நிமிடத்தில் அனுப்பப்படும்).',
  'A vehicle entered a geofence (needs the geofence alert).': 'வாகனம் ஜியோஃபென்ஸில் நுழைந்தது (ஜியோஃபென்ஸ் எச்சரிக்கை தேவை).',
  'A vehicle left a geofence (needs the geofence alert).': 'வாகனம் ஜியோஃபென்ஸிலிருந்து வெளியேறியது (ஜியோஃபென்ஸ் எச்சரிக்கை தேவை).',
