  'Add what you want to track: it starts on a free trial (phones 100 days, GPS trackers and dashcams 30 days). Buy a yearly licence before the trial ends.': 'கண்காணிக்க வேண்டியதைச் சேர்க்கவும்: இது இலவச சோதனையுடன் தொடங்கும் (ஃபோன் 100 நாட்கள், GPS டிராக்கர் மற்றும் டேஷ்கேம் 30 நாட்கள்). சோதனை முடிவதற்குள் வருடாந்திர உரிமம் வாங்கவும்.',
  'Add what you want to track. Each tracker or phone needs a yearly licence.': 'நீங்கள் கண்காணிக்க விரும்புவதைச் சேர்க்கவும். ஒவ்வொரு டிராக்கர் அல்லது தொலைபேசிக்கும் ஆண்டு உரிமம் தேவை.',
