  'Applies to {{name}}. Overspeed alerts fire above this speed. Leave empty for the vehicle-type default.': '{{name}} க்குப் பொருந்தும். இந்த வேகத்தை மீறினால் அதிவேக எச்சரிக்கைகள் வரும். வாகன வகை இயல்புநிலைக்கு காலியாக விடவும்.',
