  'Deletes this account and everything in it: every phone, tracker and dashcam, with all locations, history and settings.': 'இந்தக் கணக்கையும் அதிலுள்ள அனைத்தையும் நீக்கும்: ஒவ்வொரு ஃபோன், டிராக்கர், டேஷ்கேம் மற்றும் அனைத்து இருப்பிடங்கள், வரலாறு, அமைப்புகள்.',
  'Deletes your login. The company’s vehicles and data stay with the company.': 'உங்கள் உள்நுழைவை நீக்கும். நிறுவனத்தின் வாகனங்களும் தரவும் நிறுவனத்திடமே இருக்கும்.',
  'Deletion is immediate and cannot be undone. Encrypted backups are removed automatically within 100 days. Invoices are kept as long as tax law requires.': 'நீக்கம் உடனடியானது, திரும்பப் பெற முடியாது. குறியாக்கப்பட்ட காப்புப்பிரதிகள் 100 நாட்களில் தானாக நீக்கப்படும். விலைப்பட்டியல்கள் வரிச் சட்டப்படி வைக்கப்படும்.',
