  'E-mails go out on new WARN / CRITICAL issues and on recovery; several at once are sent as one digest. Change these with environment variables (see docs/MONITORING.md).': 'புதிய எச்சரிக்கை / முக்கிய சிக்கல்களுக்கும் சரியானதும் மின்னஞ்சல் அனுப்பப்படும்; பல ஒரே நேரத்தில் இருந்தால் ஒரே சுருக்கமாக அனுப்பப்படும். இவற்றை environment variables மூலம் மாற்றவும் (docs/MONITORING.md பார்க்கவும்).',
