  'Free for 100 days, then a yearly licence. Uses mobile data lightly and saves battery when the phone is still.': '100 நாட்கள் இலவசம், பின் வருடாந்திர உரிமம். குறைவான மொபைல் டேட்டா பயன்படுத்தும்; ஃபோன் அசையாதபோது பேட்டரியைச் சேமிக்கும்.',
