  'Inactive branches can\'t be assigned to new objects.': 'செயலற்ற கிளைகளைப் புதிய பொருட்களுக்கு ஒதுக்க முடியாது.',
  'Inactive drivers can\'t be assigned and their card is ignored.': 'செயலற்ற ஓட்டுநர்களை ஒதுக்க முடியாது, அவர்களின் அட்டை புறக்கணிக்கப்படும்.',
  'Inactive geofences raise no alerts': 'செயலற்ற ஜியோஃபென்ஸ்கள் எச்சரிக்கை எழுப்பாது',
  'Inactive objects are hidden from the live map and ignored by the processor.': 'செயலற்ற பொருட்கள் நேரலை வரைபடத்தில் மறைக்கப்படும், செயலாக்கியால் புறக்கணிக்கப்படும்.',
  'Inactive POIs are hidden from the map and reports': 'செயலற்ற POI-கள் வரைபடம் மற்றும் அறிக்கைகளில் மறைக்கப்படும்',
  'Inactive reminders raise no alerts.': 'செயலற்ற நினைவூட்டல்கள் எச்சரிக்கைகளை எழுப்பாது.',
  'Inactive schedules don\'t run automatically; Run now still works.': 'செயலற்ற அட்டவணைகள் தானாக இயங்காது; \'இப்போது இயக்கு\' இன்னும் வேலை செய்யும்.',
  'Inactive templates fall back to the system default.': 'செயலற்ற வார்ப்புருக்களுக்குப் பதிலாக சிஸ்டம் இயல்புநிலை பயன்படுத்தப்படும்.',
  'Inactive users can\'t sign in.': 'செயலற்ற பயனர்கள் உள்நுழைய முடியாது.',
