  'Optional': 'விருப்பத்தேர்வு',
  'Optional, e.g. In workshop for service': 'விருப்பத்தேர்வு, எ.கா. சர்வீஸுக்காகப் பணிமனையில்',
  'Optional, e.g. the employee who uses this phone. Administrators who can edit this device always get the code too.': 'விருப்பத்தேர்வு, எ.கா. இந்த ஃபோனைப் பயன்படுத்தும் ஊழியர். இந்தச் சாதனத்தைத் திருத்தக்கூடிய நிர்வாகிகளுக்கும் குறியீடு எப்போதும் கிடைக்கும்.',
  'Optional.': 'விருப்பத்தேர்வு.',
  'Optional. Needed to claim input tax credit.': 'விருப்பத்தேர்வு. உள்ளீட்டு வரிக் கடன் பெற தேவை.',
  'Optional. One per line or comma-separated; CIDR ranges allowed (e.g. 203.0.113.0/24).': 'விருப்பத்தேர்வு. ஒரு வரிக்கு ஒன்று அல்லது காற்புள்ளியால் பிரிக்கவும்; CIDR வரம்புகள் அனுமதிக்கப்படும் (எ.கா. 203.0.113.0/24).',
  'Optional. Used for sign-in by OTP and for your phone tracker.': 'விருப்பம். OTP உள்நுழைவுக்கும் உங்கள் தொலைபேசி டிராக்கருக்கும்.',
  'Or open app.veetrax.com/download on that phone.': 'அல்லது அந்த ஃபோனில் app.veetrax.com/download ஐத் திறக்கவும்.',
