  'Overrides for every vehicle in this branch; anything not set here is inherited from the company.': 'இந்தக் கிளையின் ஒவ்வொரு வாகனத்துக்கும் மேலெழுதல்கள்; இங்கு அமைக்காதவை நிறுவனத்திலிருந்து பெறப்படும்.',
  'Overrides for every vehicle in this group; anything not set here is inherited from the company.': 'இந்தக் குழுவின் ஒவ்வொரு வாகனத்துக்கும் மேலெழுதல்கள்; இங்கு அமைக்காதவை நிறுவனத்திலிருந்து பெறப்படும்.',
  'Overrides for this vehicle only.': 'இந்த வாகனத்துக்கு மட்டும் மேலெழுதல்கள்.',
  'Overspeed': 'அதிவேகம்',
  'Overspeed alert limit (km/h)': 'அதிவேக எச்சரிக்கை வரம்பு (km/h)',
  'Overspeed alerts fire above this speed (it overrides company and group alert settings). Leave empty for the default ({{n}} km/h).': 'இந்த வேகத்துக்கு மேல் அதிவேக எச்சரிக்கைகள் எழும் (இது நிறுவன, குழு எச்சரிக்கை அமைப்புகளை மேலெழுதும்). இயல்புநிலைக்கு ({{n}} km/h) காலியாக விடவும்.',
  'Overspeed alerts fire above this speed (it overrides company and group alert settings). Leave empty for the default.': 'இந்த வேகத்துக்கு மேல் அதிவேக எச்சரிக்கைகள் எழும் (இது நிறுவன, குழு எச்சரிக்கை அமைப்புகளை மேலெழுதும்). இயல்புநிலைக்குக் காலியாக விடவும்.',
  'Overspeed alerts fire above this speed.': 'இந்த வேகத்துக்கு மேல் அதிவேக எச்சரிக்கைகள் எழும்.',
  'Overspeed alerts for {{name}} fire above this speed. Leave empty for the default ({{limit}} km/h).': '{{name}}க்கு இந்த வேகத்துக்கு மேல் அதிவேக எச்சரிக்கைகள் எழும். இயல்புநிலைக்கு ({{limit}} km/h) காலியாக விடவும்.',
  'Overspeed alerts for {{name}} fire above this speed. Leave empty for the default.': '{{name}}க்கு இந்த வேகத்துக்கு மேல் அதிவேக எச்சரிக்கைகள் எழும். இயல்புநிலைக்குக் காலியாக விடவும்.',
