  'Partners pay these prices unless a partner price is set (Licences & Invoices → Partners). A price of 0 blocks purchases of that type.': 'கூட்டாளர் விலை அமைக்கப்படாவிட்டால் கூட்டாளர்கள் இந்த விலையைச் செலுத்துவார்கள் (உரிமங்கள் & விலைப்பட்டியல்கள் → கூட்டாளர்கள்). 0 விலை அந்த வகை வாங்குதலைத் தடுக்கும்.',
