  'Phone health: not reported yet (needs Tracker app 1.1.7 or newer).': 'ஃபோன் நிலை: இன்னும் அறிவிக்கப்படவில்லை (Tracker ஆப் 1.1.7 அல்லது புதியது தேவை).',
  'Phone stopped. It must be activated again to track.': 'தொலைபேசி நிறுத்தப்பட்டது. கண்காணிக்க மீண்டும் செயல்படுத்த வேண்டும்.',
  'Phone tracking is not available yet. Contact VeeTrax support.': 'தொலைபேசி கண்காணிப்பு இன்னும் கிடைக்கவில்லை. VeeTrax உதவியைத் தொடர்பு கொள்ளவும்.',
  'Phones tracked in your account.': 'உங்கள் கணக்கில் கண்காணிக்கப்படும் ஃபோன்கள்.',
