  'Someone must acknowledge these alerts; others are done once opened. Default: on for SOS, crash, power cut, device offline and every critical alert.': 'இந்த எச்சரிக்கைகளை யாராவது ஒப்புக்கொள்ள வேண்டும்; மற்றவை திறந்தவுடன் முடிந்துவிடும். இயல்பு: SOS, விபத்து, மின் துண்டிப்பு, சாதனம் ஆஃப்லைன் மற்றும் ஒவ்வொரு அவசர எச்சரிக்கைக்கும் இயக்கத்தில்.',
