  'Stop this phone': 'இந்தத் தொலைபேசியை நிறுத்து',
  'Stop tracking on this phone? It must be activated again.': 'இந்தத் தொலைபேசியில் கண்காணிப்பை நிறுத்தவா? மீண்டும் செயல்படுத்த வேண்டும்.',
  'Stop video': 'வீடியோவை நிறுத்து',
  'Stopped': 'நிறுத்தம்',
  'Stops': 'நிறுத்தங்கள்',
  'Stops with the engine running — fuel wasted while stationary.': 'எஞ்சின் இயங்கும்போது நிறுத்தங்கள் — நின்றபடி வீணான எரிபொருள்.',
  'Storage quota (MB)': 'சேமிப்பு வரம்பு (MB)',
  'Store it in your system’s secret store. Anyone with this key can read your fleet data.': 'இதை உங்கள் அமைப்பின் ரகசியச் சேமிப்பில் வைக்கவும். இந்த விசை உள்ள எவரும் உங்கள் வாகனத் தரவைப் படிக்க முடியும்.',
  'Stream length': 'ஸ்ட்ரீம் நீளம்',
  'Subject': 'பொருள்',
  'Subject:': 'பொருள்:',
  'Submit cash payment': 'ரொக்கக் கட்டணத்தைச் சமர்ப்பி',
