  'Vehicles marked as in maintenance from the live map: alerts are paused until maintenance ends.': 'நேரடி வரைபடத்திலிருந்து பராமரிப்பில் எனக் குறிக்கப்பட்ட வாகனங்கள்: பராமரிப்பு முடியும் வரை எச்சரிக்கைகள் இடைநிறுத்தப்படும்.',
  'Vehicles that need attention: inactive, no GPS, wrong time zone or never connected.': 'கவனம் தேவைப்படும் வாகனங்கள்: செயலற்றவை, GPS இல்லாதவை, தவறான நேர மண்டலம் அல்லது ஒருபோதும் இணையாதவை.',
