  'Webhooks': 'வெப்ஹூக்குகள்',
  'Webhooks push events to your system as they happen, signed with HMAC-SHA256. Endpoints that fail 50 times in a row are switched off automatically.': 'வெப்ஹூக்குகள் நிகழ்வுகளை நடக்கும்போதே HMAC-SHA256 கையொப்பத்துடன் உங்கள் அமைப்புக்கு அனுப்பும். தொடர்ந்து 50 முறை தோல்வியடையும் முனையங்கள் தானாக அணைக்கப்படும்.',
  'Website': 'இணையதளம்',
