  'Welcome': 'வரவேற்கிறோம்',
  'Welcome back. Sign in to your VeeTrax account.': 'மீண்டும் வருக. உங்கள் VeeTrax கணக்கில் உள்நுழையவும்.',
  'What each role can see and do. Data scope limits users to their branches and mapped objects.': 'ஒவ்வொரு பங்கும் என்ன பார்க்கலாம், செய்யலாம். தரவு வரம்பு பயனர்களை அவர்களின் கிளைகள் மற்றும் இணைக்கப்பட்ட பொருட்களுக்கு மட்டுப்படுத்துகிறது.',
  'What is deleted': 'என்ன நீக்கப்படும்',
  'What was checked or done?': 'என்ன சரிபார்க்கப்பட்டது அல்லது செய்யப்பட்டது?',
  'What was done?': 'என்ன செய்யப்பட்டது?',
  'WhatsApp': 'WhatsApp',
  'When the free trial ends, choose how many trackers and phones to keep. Pay by UPI or cash; we activate them once paid.': 'இலவச சோதனை முடிந்ததும் எத்தனை டிராக்கர்கள் மற்றும் ஃபோன்களை வைத்திருக்க வேண்டும் எனத் தேர்வுசெய்யவும். UPI அல்லது ரொக்கமாகச் செலுத்துங்கள்; செலுத்தியதும் செயல்படுத்துவோம்.',
  'When the geofence is active (company timezone).': 'ஜியோஃபென்ஸ் எப்போது செயலில் இருக்கும் (நிறுவன நேர மண்டலம்).',
  'Who receives alerts when an alert type has no list of its own. Branches, groups and vehicles inherit these and can add to or replace them.': 'ஒரு எச்சரிக்கை வகைக்குத் தனிப் பட்டியல் இல்லாதபோது யார் எச்சரிக்கைகளைப் பெறுவார்கள். கிளைகள், குழுக்கள் மற்றும் வாகனங்கள் இவற்றைப் பெற்று, சேர்க்கலாம் அல்லது மாற்றலாம்.',
  'Whole company': 'முழு நிறுவனம்',
  'will be deleted and the system default used again.': 'நீக்கப்பட்டு மீண்டும் சிஸ்டம் இயல்புநிலை பயன்படுத்தப்படும்.',
  'will be permanently deleted. Records that are in use can\'t be deleted — deactivate them instead.': 'நிரந்தரமாக நீக்கப்படும். பயன்பாட்டில் உள்ள பதிவுகளை நீக்க முடியாது — அதற்குப் பதிலாக அவற்றைச் செயலிழக்கச் செய்யவும்.',
  'With snapshot': 'ஸ்னாப்ஷாட்டுடன்',
