  'Your licences are activated once we have received the cash. The GST invoice is emailed to you.': 'பணம் கிடைத்ததும் உங்கள் உரிமங்கள் செயல்படுத்தப்படும். GST விலைப்பட்டியல் உங்களுக்கு மின்னஞ்சல் செய்யப்படும்.',
  'your login and personal settings. The company’s vehicles and data belong to the company; ask your administrator about them.': 'உங்கள் உள்நுழைவும் தனிப்பட்ட அமைப்புகளும். நிறுவனத்தின் வாகனங்களும் தரவும் நிறுவனத்துக்குச் சொந்தம்; அவற்றைப் பற்றி உங்கள் நிர்வாகியிடம் கேளுங்கள்.',
